    },
    [65] = {
      beijing = 4994,
      dialog = 3,
      music = "1025_2024qixi",
      renwu = "npc",
      sentence = "Everyone wants to be pretty, but ever since I fell gravely ill... I was getting more emaciated by the day, and my face was as pale as a sheet. I hadn't had the heart to try to doll myself up.",
      next = {66}
    },
    [66] = {
      beijing = 4994,
      dialog = 3,
      music = "1025_2024qixi",
      renwu = "npc",
      sentence = "But now, my complexion was rich as cream, and the string of coral beads on my wrist was the pièce de résistance, adding a touch of appealing vitality.",
