      renwu = "npc",
      role1 = 3175000,
      role2 = 3175101,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "Only every day and twice on Sundays. You're always giving me a glimmer of hope only to snuff it out later.",
      next = {73}
    },
    [73] = {
