      dialog = 3,
      music = "1025_2024qixi",
      renwu = "npc",
      role1 = 3175000,
      role2 = 3175104,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "His eyebrows perked up, and he chuckled.",
