      music = "1025_2024qixi",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3175000,
      role2 = 3175101,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "Because you're so cute when you're like that. I never get tired of looking at you.",
