      renwu = "npc",
      role1 = 3175000,
      role2 = 3175106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "Ordinary people are already so expressive and emotional, but you're even more so. In the whole world... you're one-of-a-kind.",
